technical.api_contract:
GET /api/projects/{id}/prompts?filter={role|base|standards}&key={PromptKey} — list project prompts
POST /api/projects/{id}/prompts — upsert prompt
{ prompt_key: string, variant: "role"|"base"|"standards"|"constraint", content: string }
PATCH /api/projects/{id}/prompts/{key} — partial update
{ content?: string, archived?: boolean }
DELETE /api/projects/{id}/prompts/{key} — soft-delete
GET /api/projects/{id}/prompts/resolve?key={PromptKey} — get effective (merged) prompt
POST /api/projects/{id}/prompts/preview — dry-run resolution (for UI)
{ key: string, candidate_content: string } → { full_system_prompt: string, source_breakdown: [{layer: string, source: string, length: number}] }
Responses: 200 OK, 204 No Content, 404 Not Found (key not set), 400 Bad Request (validation), 401/403 Auth errors
